    # Also keep a floor to avoid losing to moderate bids when supply is tight.
    floor_bid = DAILY_SALARY * (0.35 + 0.25 * tightness)
    bid = max(floor_bid, target)

    if bid > budget:
        bid = budget

    # If budget is very low, still bid at least a small amount.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

